vertex:
#version 300 es

struct VS_OUT
{
    vec2 texCoords;
};

out vec2 vdspv_fsin0_texCoords;
layout(location = 2) in vec2 texCoords;
layout(location = 0) in vec3 position;
layout(location = 1) in vec3 normal;

void main()
{
    vdspv_fsin0_texCoords = texCoords;
    gl_Position = vec4(position, 1.0);
    gl_Position.z = 0.0;
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

struct VS_OUT
{
    highp vec2 texCoords;
};

uniform highp sampler2D Color;

layout(location = 0) out highp vec4 out_color;
in highp vec2 vdspv_fsin0_texCoords;

void main()
{
    out_color = texture(Color, vec2(vdspv_fsin0_texCoords.x, 1.0 - vdspv_fsin0_texCoords.y));
    if (out_color.w == 0.0)
    {
        discard;
    }
}
